import{_ as i,C as r,o as l,c as p,j as t,a as o,E as e,aj as a}from"./chunks/framework.m090XgxO.js";const k=JSON.parse('{"title":"Popconfirm","description":"","frontmatter":{},"headers":[],"relativePath":"components/popconfirm.md","filePath":"components/popconfirm.md","lastUpdated":1789206102000}'),h={name:"components/popconfirm.md"},s={id:"popconfirm",tabindex:"-1"};function f(m,d,g,b,u,x){const n=r("Badge"),c=r("XhDemo");return l(),p("div",null,[t("h1",s,[d[0]||(d[0]=o("Popconfirm ",-1)),e(n,{type:"info",text:"弹出确认"}),d[1]||(d[1]=o()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#popconfirm","aria-label":'Permalink to "Popconfirm <Badge type="info" text="弹出确认" />"'},"​",-1))]),d[3]||(d[3]=a('<p>贴着触发器的一句确认：比对话框轻，但仍拦住一次误操作。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/popconfirm" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/popconfirm.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/popconfirm" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/popconfirm" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/popconfirm.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>点触发器就地问一句，确认与取消都收起浮层；展开时焦点先落在取消上</p>',4)),e(c,{src:"popconfirm/01-basic"}),d[4]||(d[4]=t("h2",{id:"示例",tabindex:"-1"},[o("示例 "),t("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),d[5]||(d[5]=t("h3",{id:"放置位",tabindex:"-1"},[o("放置位 "),t("a",{class:"header-anchor",href:"#放置位","aria-label":'Permalink to "放置位"'},"​")],-1)),d[6]||(d[6]=t("p",null,"placement 是首选位，位置不够时引擎自己避让，实际落点写在 data-placement 上",-1)),e(c,{src:"popconfirm/02-placement"}),d[7]||(d[7]=t("h3",{id:"尺寸",tabindex:"-1"},[o("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[8]||(d[8]=t("p",null,"size 换的是面板的内边距与最大宽度，三个档位落在 content 上",-1)),e(c,{src:"popconfirm/03-size"}),d[9]||(d[9]=t("h3",{id:"语气",tabindex:"-1"},[o("语气 "),t("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),d[10]||(d[10]=t("p",null,"在 content 上写 data-tone，确认按钮跟着换色；语气是共享的一层，不是本组件的 prop",-1)),e(c,{src:"popconfirm/04-tone"}),d[11]||(d[11]=t("h3",{id:"异步确认",tabindex:"-1"},[o("异步确认 "),t("a",{class:"header-anchor",href:"#异步确认","aria-label":'Permalink to "异步确认"'},"​")],-1)),d[12]||(d[12]=t("p",null,"确认回调返回 Promise 即挂起确认门：浮层等兑现才收起、确认按钮转圈且再点无效，落空（reject）留在原地；不必再手动受控拦收起",-1)),e(c,{src:"popconfirm/05-async-confirm"}),d[13]||(d[13]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>影响有限、可撤销的删除或清空，且触发器就在近处。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>后果严重不可逆：用<a href="./dialog">对话框</a>，并让用户读到完整说明。</li><li>操作可以撤销：干脆直接做，配一条带&quot;撤销&quot;的<a href="./toast">轻提示</a>——那比事前确认体验好。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>确认按钮支持同步返回和任意 thenable：调用业务前即占用事务，兑现后收起；同步抛错、 <code>then</code> 读取失败或拒绝都会保持打开，并通过 <code>actionError</code> 与 <code>confirm-error</code> 原样暴露 <code>cause</code>。</li><li>pending 期间重复确认、触发器切换、<code>setOpen(false)</code>、Escape 与层外交互都不会关闭。 取消仍可立即终止组件的等待并收起；它不会假装取消业务 Promise，迟到的兑现或拒绝会按事务票据丢弃。</li><li>受控宿主把 <code>open</code> 写成 <code>false</code> 属于事实状态，会终止当前确认事务；此后重新写成 <code>true</code> 是新会话， 旧 thenable 的结算不会关闭它或写入错误。</li><li>浮层是非模态 <code>dialog</code>：不陷焦点、不锁滚动、不隐藏页面其它内容。</li><li>位置、尺寸、语气三轴。</li><li>内容与箭头使用和 Popover 同源的 M2 磨砂表面：边界、顶光、背景模糊与投影保持连续； 强制颜色模式会撤掉装饰顶光，由系统色接管边界。</li><li>标题、说明与末行操作按固定节奏排布，长文案可在可用宽度内断行。确认是实心主操作， 取消是 soft 次操作；两颗按钮都有接触高光、按压回执、明确的不透明聚焦底与粗指针命中区。</li><li>pending 时在确认文案之前显示 spinner，并以 <code>aria-busy</code> / <code>aria-disabled</code> 报告状态；挂起时按钮不再响应 hover / active 换面， 减弱动效下以静止点线圆环表达在途。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-popconfirm&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhPopconfirmArrow</code> <code>XhPopconfirmCancelTrigger</code> <code>XhPopconfirmConfirmTrigger</code> <code>XhPopconfirmContent</code> <code>XhPopconfirmDescription</code> <code>XhPopconfirmPositioner</code> <code>XhPopconfirmRoot</code> <code>XhPopconfirmTitle</code> <code>XhPopconfirmTrigger</code></td></tr><tr><td>组合式函数</td><td><code>usePopconfirm</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/popconfirm.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;popconfirm&quot;</code>：<strong><code>root</code></strong> · <strong><code>trigger</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <code>title</code> · <code>description</code> · <strong><code>confirm-trigger</code></strong> · <strong><code>cancel-trigger</code></strong> · <code>arrow</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>closeOnEscape</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>closeOnInteractOutside</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 ltr。只改写浮层在行内轴上 start 与 end 的落点。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>onCancel</code></td><td><code>() =&gt; void</code></td><td></td><td>点了取消按钮，随后浮层收起；挂起中的确认结果随之作废。Escape 与层外交互只发 onOpenChange，不发这条。</td></tr><tr><td><code>onConfirm</code></td><td><code>() =&gt; void | PromiseLike&lt;unknown&gt;</code></td><td></td><td>点了确认按钮。返回 thenable 即挂起确认门：浮层等它兑现才收起、 确认按钮转圈且再点无效，拒绝则留在原地并报告确认错误。同步返回照旧立即收起。</td></tr><tr><td><code>onConfirmError</code></td><td><code>(details: PopconfirmConfirmErrorDetails) =&gt; void</code></td><td></td><td>确认回调同步抛出或 thenable 拒绝；details.cause 是未经包装的原始原因。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: PopoverOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td></td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定面板的内边距档位。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>PopoverOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr><tr><td><code>confirm</code></td><td>``</td><td>点了确认按钮；随后浮层收起。异步门走 confirmAction 属性： 事件拿不到监听函数的返回值，给元素赋 <code>confirmAction = () =&amp;gt; thenable</code> 即挂起确认门 （浮层等兑现才收、确认按钮转圈，拒绝留在原地），confirm 事件照发只作通知</td></tr><tr><td><code>confirm-error</code></td><td><code>PopconfirmConfirmErrorDetails</code></td><td>确认动作同步抛出或 thenable 拒绝；detail 为 <code>{ cause }</code>，保留原始原因</td></tr><tr><td><code>cancel</code></td><td>``</td><td>点了取消按钮；随后浮层收起</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhPopconfirmRoot</code></td><td><code>default</code></td><td><code>PopconfirmRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>usePopconfirm</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>pending</code></td><td><code>boolean</code></td><td>异步确认进行中：确认按钮转圈、再点无效。</td></tr><tr><td><code>actionError</code></td><td><code>PopconfirmConfirmErrorDetails | null</code></td><td>最近一次有效确认动作的错误；新确认或取消时清空。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>confirm</code></td><td><code>() =&gt; void</code></td><td>发确认意图并请求收起；异步确认挂起期间再调无效。</td></tr><tr><td><code>cancel</code></td><td><code>() =&gt; void</code></td><td>发取消意图并请求收起。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getConfirmTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCancelTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getArrowProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/TR/wai-aria-1.2/#dialog" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger</td><td>切换开合，展开时把焦点移入 content</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in confirm-trigger</td><td>发确认意图；同步成功或 thenable 兑现后收起</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in cancel-trigger</td><td>终止组件等待，发取消意图并收起浮层</td></tr><tr><td><code>Escape</code></td><td>open and not pending</td><td>收起浮层并把焦点还给 trigger；不发确认也不发取消</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-haspopup</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-hidden</code></td><td>!open || undefined</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>confirm-trigger</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>confirm-trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>arrow</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/popconfirm.css</code> 按部件选择：<code>[data-scope=&quot;popconfirm&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>content</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>confirm-trigger</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>arrow</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-popconfirm-action-px</code></td><td><code>cancel-trigger</code><br><code>confirm-trigger</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-control-px-sm</code></td><td>popconfirm 的 cancel-trigger、confirm-trigger 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-action-radius</code></td><td><code>cancel-trigger</code><br><code>confirm-trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>popconfirm 的 cancel-trigger、confirm-trigger 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-action-shadow</code></td><td><code>cancel-trigger</code><br><code>confirm-trigger</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>hover</code><br><code>loading</code><br><code>not([data-loading])</code></td><td><code>--xh-_popconfirm-confirm-highlight</code><br><code>--xh-material-soft-shadow</code></td><td>popconfirm 的 cancel-trigger、confirm-trigger 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-arrow-size</code></td><td><code>arrow</code></td><td><code>--xh-_overlay-arrow-size</code></td><td><code>default</code></td><td><code>--xh-overlay-arrow-size</code></td><td>popconfirm 的 arrow 部件 --xh-_overlay-arrow-size 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-backdrop</code></td><td><code>content</code></td><td><code>-webkit-backdrop-filter</code><br><code>backdrop-filter</code></td><td><code>default</code></td><td><code>--xh-material-frosted-backdrop</code></td><td>popconfirm 的 content 部件 -webkit-backdrop-filter、backdrop-filter 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-bg</code></td><td><code>arrow</code><br><code>content</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-material-frosted-bg</code></td><td>popconfirm 的 arrow、content 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-border</code></td><td><code>arrow</code><br><code>content</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-material-frosted-border</code></td><td>popconfirm 的 arrow、content 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-cancel-bg</code></td><td><code>cancel-trigger</code></td><td><code>background-color</code></td><td><code>default</code></td><td><code>--xh-material-soft-bg</code></td><td>popconfirm 的 cancel-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-cancel-bg-focus</code></td><td><code>cancel-trigger</code></td><td><code>background-color</code></td><td><code>focus-visible</code></td><td><code>--xh-material-soft-focus-surface</code></td><td>popconfirm 的 cancel-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-cancel-fg</code></td><td><code>cancel-trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-material-soft-fg</code></td><td>popconfirm 的 cancel-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-cancel-fg-focus</code></td><td><code>cancel-trigger</code></td><td><code>color</code></td><td><code>focus-visible</code></td><td><code>--xh-material-soft-fg</code></td><td>popconfirm 的 cancel-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-confirm-bg</code></td><td><code>confirm-trigger</code></td><td><code>background-color</code></td><td><code>default</code><br><code>focus-visible</code></td><td><code>--xh-_tone</code></td><td>popconfirm 的 confirm-trigger 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-confirm-fg</code></td><td><code>confirm-trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-_tone-on</code></td><td>popconfirm 的 confirm-trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-confirm-shadow</code></td><td><code>cancel-trigger</code><br><code>confirm-trigger</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>hover</code><br><code>loading</code><br><code>not([data-loading])</code></td><td><code>--xh-popconfirm-action-shadow</code></td><td>popconfirm 的 cancel-trigger、confirm-trigger 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-description-fg</code></td><td><code>description</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-material-frosted-fg-muted</code></td><td>popconfirm 的 description 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-fg</code></td><td><code>content</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-material-frosted-fg</code></td><td>popconfirm 的 content 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-gap</code></td><td><code>content</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>popconfirm 的 content 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-layer</code></td><td><code>positioner</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-_layer</code></td><td>popconfirm 的 positioner 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-loading-duration</code></td><td><code>confirm-trigger</code></td><td><code>animation</code></td><td><code>loading</code></td><td><code>--xh-spin-duration</code></td><td>popconfirm 的 confirm-trigger 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-max-h</code></td><td><code>content</code></td><td><code>max-block-size</code></td><td><code>default</code></td><td><code>--xh-overlay-max-h</code></td><td>popconfirm 的 content 部件 max-block-size 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-max-w</code></td><td><code>content</code></td><td><code>max-inline-size</code></td><td><code>default</code></td><td><code>--xh-_popconfirm-max-w</code></td><td>popconfirm 的 content 部件 max-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-px</code></td><td><code>content</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_popconfirm-pad</code></td><td>popconfirm 的 content 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-py</code></td><td><code>content</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-_popconfirm-pad</code></td><td>popconfirm 的 content 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-radius</code></td><td><code>content</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-surface</code></td><td>popconfirm 的 content 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-shadow</code></td><td><code>content</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-material-frosted-shadow</code></td><td>popconfirm 的 content 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-title-fg</code></td><td><code>title</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-material-frosted-fg</code></td><td>popconfirm 的 title 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-title-font-size</code></td><td><code>title</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>popconfirm 的 title 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-popconfirm-title-font-weight</code></td><td><code>title</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-semibold</code></td><td>popconfirm 的 title 部件 font-weight 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-overlay-pop-in</code> · <code>xh-pop-out</code> · <code>xh-popconfirm-rotate</code> 随皮肤自带，不引用别处文件里的名字；<code>background-color</code> · <code>border-color</code> · <code>box-shadow</code> · <code>color</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：退场由适配器的退场闸门把关，动画播完才真收起。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h2><p>皮肤另按输入能力分档：<code>pointer: coarse</code>——同一份皮肤在触屏与带指针的设备上不一样，与视口宽度无关。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>触发器用<a href="./button">按钮</a>；放进<a href="./table">表格</a>的行操作、<a href="./menu">菜单</a>的条目旁。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>标题直接问那件事（&quot;删除这条记录？&quot;），描述写清后果。</li><li>确认按钮写动作名，并对破坏性操作用危险语气。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>每一个操作都要确认：用户会条件反射地点确认，确认就失去意义了。</li><li>确认框里没说清楚要删的是哪一条。</li></ul>',55))])}const q=i(h,[["render",f]]);export{k as __pageData,q as default};
